// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 firstVal, uint256 secondVal) public {
        vm.assume(firstVal != secondVal);
        // two consecutive SetMinSum calls, neither blocked by Initialized
        vm.prank(address(0x1));
        c.SetMinSum(firstVal);
        vm.prank(address(0x2));
        c.SetMinSum(secondVal);
        // Rule: while not Initialized, any SetMinSum call succeeds and sets MinSum to its argument
        assertEq(c.MinSum(), secondVal);
    }
}
